import { memo, useEffect, useCallback } from 'react'

import { Box, Text } from '@chakra-ui/react'

import { paths } from '~/paths'
import { MethodDrawer, useMethodDrawer } from '~/ui/layout/MethodDrawer'
import { SectionCard } from '~/ui/layout/item/SectionCard'
import { useItemCardSelectTarget, type SelectTarget } from '~/ui/layout/item/ItemCard'
import { Remarks, halfWidthStyle } from '~/ui/layout/item/explanation'
import { useMenuContext } from '~/ui/layout/menu'

import { LetterDecoration } from './iron/letterDecoration'
import { CylinderOrnament } from './iron/cylinderOrnament'
import { PiggyBank } from './iron/piggyBank'
import { BallOrnament } from './iron/ballOrnament'
import { DogGreeting } from './iron/dogGreeting'
import { SingleFlower } from './iron/singleFlower'
import { BunkBed } from './iron/bunkBed'

import { BoxWithLid } from './iron/boxWithLid'


/** @jsxImportSource @emotion/react */
//import { css } from '@emotion/react'


export default function BeadsItemsImpl() {
  const { open, onDrawerOpenChange, openDrawer } = useMethodDrawer(
    paths.beads.path(), 
    useCallback((kind: string, name: string) => `${kind}#${name}`, [])
  );
  const selectTarget = useItemCardSelectTarget(paths.beads.path());
  
  const { setItemsComponent, setRecipesComponent } = useMenuContext();
  useEffect(() => {
    setItemsComponent([
      { title: '立体アイロンビーズ：', items: [
        { title: 'お手紙デコレーション', href: '#letter-decoration' },
        { title: 'シリンダー装飾', href: '#cylinder-ornament' },
        { title: '貯金箱', href: '#piggy-bank' },
        { title: 'ボール型装飾', href: '#ball-ornament' },
        { title: 'お出迎え犬', href: '#dog-greeting' },
        { title: '一輪の花', href: '#single-flower' },
        { title: '二段ベッド', href: '#bunk-bed' },
      ]},
      { title: '動くアイロンビーズ：', items: [
        { title: 'フタを開けれるボックス', href: '#box-with-a-lid' },
      ]}
    ]);
    setRecipesComponent([
     { title: 'アイロンビーズのレシピ集', href: paths.beads.method.iron.path() }
    ]);
  }, []);
  
  return (
    <>
      <MyMainArea>
        <Detail openDrawer={openDrawer} selectTarget={selectTarget} />
      </MyMainArea>
      <MethodDrawer open={open} onDrawerOpenChange={onDrawerOpenChange} />
    </>
  )
}



import { MyMainArea } from '~/ui/layout/MyMain'


type DetailProp = {
  openDrawer: (kind: string, name: string) => () => void;
  selectTarget :SelectTarget;
}
const Detail = memo(function Detail(prop: DetailProp) {
  const { openDrawer, selectTarget } = prop;
  return (
    <>
      <SectionCard title={<Box w='6em' display='flex' flexDirection='row'>立体<Text as='span' css={halfWidthStyle}>アイロンビーズ</Text></Box>} 
        prelude={<>
        いろいろな方法で平面から飛び出したアイロンビーズの作品。<br/>
        組み立てのレベル(難しさ)が簡単なモノから順に載せているので、トライしてもらえたら嬉しいです。<br/>
        <Remarks mark='※'>
          "レベル"は、娘がこれを見て自分のアレンジで作る姿を元につけてます<br/>
          (アイロンがけの難しさは加味してません)
        </Remarks>
        </>}
        >
        <LetterDecoration openDrawer={openDrawer} selectTarget={selectTarget} />
        <CylinderOrnament openDrawer={openDrawer} selectTarget={selectTarget} />
        <PiggyBank openDrawer={openDrawer} selectTarget={selectTarget} />
        <BallOrnament openDrawer={openDrawer} selectTarget={selectTarget} />
        <DogGreeting openDrawer={openDrawer} selectTarget={selectTarget} />
        <SingleFlower openDrawer={openDrawer} selectTarget={selectTarget} />
        <BunkBed openDrawer={openDrawer} selectTarget={selectTarget} />
      </SectionCard>
      <SectionCard title={<Box w='6em' display='flex' flexDirection='row'>動く<Text as='span' css={halfWidthStyle}>アイロンビーズ</Text></Box>} 
        prelude={<>
        ドアやフタを開けたり閉じたりと、動かすことができるアイロンビーズの作品。<br/>
        組み立てのレベル(難しさ)が簡単なモノから順に載せているので、トライしてもらえたら嬉しいです。<br/>
        <Remarks mark='※'>
          "レベル"は、娘がこれを見て自分のアレンジで作る姿を元につけてます<br/>
          (アイロンがけの難しさは加味してません)
        </Remarks>
        </>}
        >
        <BoxWithLid openDrawer={openDrawer} selectTarget={selectTarget} />
      </SectionCard>
    </>
  )
}, (prop1, prop2) => (prop1.openDrawer === prop2.openDrawer && prop1.selectTarget === prop2.selectTarget))

